/* ==========================================================================
   No Man's Sky 2D - Complete Unified Master CSS Theme
   Authentic Sci-Fi HUD & UI / UX System (UI-01 ~ UI-1717 Comprehensive)
   Optimized for Web & Mobile Viewports (100dvh, Safe-Area & 120Hz ProMotion)
   Target URL: https://nomansky.ai.studio
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Geist:wght@300;500;700;900&family=Orbitron:wght@500;700;900&family=Rajdhani:wght@500;600;700&display=swap');

/* ==========================================================================
   1. GLOBAL TOKENS & SYSTEM VARIABLES
   ========================================================================== */
:root {
  /* NMS Signature Neon Palette */
  --nms-cyan: #00e5ff;
  --nms-cyan-glow: rgba(0, 229, 255, 0.45);
  --nms-yellow: #ffb703;
  --nms-yellow-glow: rgba(255, 183, 3, 0.4);
  --nms-red: #ff3366;
  --nms-red-glow: rgba(255, 51, 102, 0.5);
  --nms-orange: #fb8500;
  --nms-green: #06d6a0;
  --nms-blue: #219ebc;
  --nms-purple: #a855f7;
  --nms-magenta: #d946ef;
  --nms-gold: #facc15;
  --nms-obsidian: #050b14;

  /* Surfaces & Glassmorphism */
  --nms-hud-bg: rgba(7, 14, 24, 0.86);
  --nms-hud-border: rgba(0, 229, 255, 0.35);
  --nms-card-bg: linear-gradient(135deg, rgba(3, 10, 24, 0.92) 0%, rgba(8, 22, 45, 0.95) 100%);
  --nms-clip-corner: polygon(0 6px, 6px 0, calc(100% - 6px) 0, 100% 6px, 100% calc(100% - 6px), calc(100% - 6px) 100%, 6px 100%, 0 calc(100% - 6px));

  /* Motion & Haptic Scaling */
  --shake-multiplier: 1;
}

/* Base Body & Viewport Lockdown */
html, body {
  margin: 0;
  padding: 0;
  width: 100vw;
  height: 100dvh;
  overflow: hidden;
  background: #02040a;
  touch-action: none;
  font-family: 'Rajdhani', -apple-system, BlinkMacSystemFont, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  color: #fff;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

canvas {
  display: block;
  width: 100vw;
  height: 100vh;
}

/* ==========================================================================
   2. VISOR GLASS & ENVIRONMENTAL POST-PROCESSING
   ========================================================================== */
.scanlines {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 90;
  background: repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.15) 0px, rgba(0, 0, 0, 0.15) 1px, transparent 1px, transparent 3px);
  opacity: 0.35;
}

.vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 89;
  background: radial-gradient(circle at center, transparent 55%, rgba(1, 4, 10, 0.85) 100%);
}

#visor-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 105;
  display: none;
  background: radial-gradient(circle, transparent 40%, rgba(0, 229, 255, 0.12) 100%),
              repeating-linear-gradient(0deg, rgba(0, 229, 255, 0.04) 0px, rgba(0, 229, 255, 0.04) 1px, transparent 1px, transparent 4px);
  border: 2px solid rgba(0, 229, 255, 0.3);
  box-shadow: inset 0 0 50px rgba(0, 229, 255, 0.2);
}

#damage-flash {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 108;
  background: radial-gradient(circle at center, transparent 45%, rgba(255, 51, 102, 0.65) 100%);
  opacity: 0;
  transition: opacity 0.15s ease-out;
}

/* ==========================================================================
   3. NAVIGATION COMPASS & DIRECTIONAL HUD
   ========================================================================== */
#compass-bar {
  position: fixed;
  top: max(12px, env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  width: min(640px, 88vw);
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(90deg, transparent 0%, rgba(6, 15, 28, 0.85) 15%, rgba(6, 15, 28, 0.85) 85%, transparent 100%);
  border-top: 1px solid rgba(0, 229, 255, 0.35);
  border-bottom: 1px solid rgba(0, 229, 255, 0.35);
  box-shadow: 0 0 15px rgba(0, 229, 255, 0.15);
  z-index: 120;
  overflow: hidden;
  backdrop-filter: blur(4px);
}

#reticle {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 54px;
  height: 54px;
  pointer-events: none;
  z-index: 110;
}

#interact-ring-container {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 80px;
  height: 80px;
  pointer-events: none;
  display: none;
  z-index: 130;
}

/* ==========================================================================
   4. BANNERS & NOTIFICATION SYSTEMS
   ========================================================================== */
#discovery-banner {
  position: fixed;
  top: 14%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--nms-card-bg);
  border: 1px solid var(--nms-cyan);
  clip-path: var(--nms-clip-corner);
  padding: 18px 40px;
  box-shadow: 0 0 35px var(--nms-cyan-glow), inset 0 0 20px rgba(0, 229, 255, 0.15);
  text-align: center;
  z-index: 150;
  display: none;
  pointer-events: none;
  animation: bannerPop 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes bannerPop {
  0% { transform: translate(-50%, -24px) scale(0.92); opacity: 0; }
  100% { transform: translate(-50%, 0) scale(1); opacity: 1; }
}

#pirate-banner {
  position: fixed;
  top: 68px;
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(90deg, transparent, rgba(220, 38, 38, 0.85) 20%, rgba(220, 38, 38, 0.85) 80%, transparent);
  border-top: 2px solid var(--nms-red);
  border-bottom: 2px solid var(--nms-red);
  padding: 10px 48px;
  text-align: center;
  z-index: 140;
  display: none;
  pointer-events: none;
  animation: pulseRed 0.8s infinite alternate;
}

@keyframes pulseRed {
  0% { box-shadow: 0 0 15px rgba(239, 68, 68, 0.3); }
  100% { box-shadow: 0 0 35px rgba(239, 68, 68, 0.8); }
}

#standing-banner {
  position: fixed;
  top: max(24px, env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(135deg, rgba(8, 16, 32, 0.95) 0%, rgba(20, 36, 65, 0.95) 100%);
  border: 1.5px solid var(--nms-yellow);
  clip-path: var(--nms-clip-corner);
  padding: 12px 36px;
  box-shadow: 0 0 30px var(--nms-yellow-glow);
  z-index: 160;
  display: none;
  animation: bannerDrop 0.35s cubic-bezier(0.18, 0.89, 0.32, 1.28);
}

@keyframes bannerDrop {
  0% { transform: translate(-50%, -30px) scale(0.9); opacity: 0; }
  100% { transform: translate(-50%, 0) scale(1); opacity: 1; }
}

/* ==========================================================================
   5. ANALYSIS VISOR & TARGET CODEX
   ========================================================================== */
#visor-target-card {
  position: fixed;
  bottom: max(100px, calc(env(safe-area-inset-bottom) + 80px));
  right: max(20px, env(safe-area-inset-right));
  width: min(320px, 85vw);
  background: rgba(3, 10, 24, 0.9);
  border: 1px solid var(--nms-cyan);
  border-left: 4px solid var(--nms-cyan);
  border-radius: 4px;
  padding: 14px 18px;
  color: #fff;
  display: none;
  z-index: 120;
  pointer-events: none;
  box-shadow: 0 0 25px var(--nms-cyan-glow);
  backdrop-filter: blur(8px);
}

/* ==========================================================================
   6. EXOSUIT, SENTINEL & COMBAT SYSTEMS
   ========================================================================== */
#sentinel-alert-container {
  position: fixed;
  top: max(16px, env(safe-area-inset-top));
  right: max(170px, calc(env(safe-area-inset-right) + 160px));
  display: flex;
  align-items: center;
  gap: 6px;
  z-index: 120;
}

.sentinel-diamond {
  width: 14px;
  height: 14px;
  transform: rotate(45deg);
  background: rgba(15, 25, 38, 0.8);
  border: 1.5px solid rgba(255, 255, 255, 0.3);
  transition: all 0.2s ease;
}

.sentinel-diamond.active {
  background: var(--nms-red);
  border-color: #fff;
  box-shadow: 0 0 12px var(--nms-red-glow);
  animation: diamondFlash 0.6s infinite alternate;
}

@keyframes diamondFlash {
  from { opacity: 0.6; transform: rotate(45deg) scale(0.95); }
  to { opacity: 1; transform: rotate(45deg) scale(1.1); }
}

#multitool-hud {
  position: fixed;
  top: max(16px, env(safe-area-inset-top));
  right: max(16px, env(safe-area-inset-right));
  background: var(--nms-card-bg);
  border: 1px solid rgba(0, 229, 255, 0.35);
  clip-path: var(--nms-clip-corner);
  padding: 10px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  z-index: 120;
  backdrop-filter: blur(8px);
}

.heat-meter-bar {
  width: 140px;
  height: 6px;
  background: rgba(20, 30, 45, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 2px;
  overflow: hidden;
}

.heat-meter-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--nms-cyan) 0%, var(--nms-yellow) 65%, var(--nms-red) 100%);
  transition: width 0.1s linear;
}

#critical-hazard-flash {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 109;
  background: radial-gradient(circle at center, transparent 40%, rgba(220, 38, 38, 0.4) 70%, rgba(239, 68, 68, 0.85) 100%);
  opacity: 0;
  transition: opacity 0.1s ease;
}

.shield-broken-active {
  opacity: 1 !important;
  animation: emergencySiren 0.5s infinite alternate cubic-bezier(0.4, 0, 0.6, 1);
}

@keyframes emergencySiren {
  0% { filter: brightness(1); }
  100% { filter: brightness(1.4) drop-shadow(0 0 20px #ef4444); }
}

/* ==========================================================================
   7. INVENTORY, TECH SUPERCHARGE & SYNERGY
   ========================================================================== */
.nms-panel {
  background: var(--nms-hud-bg);
  backdrop-filter: blur(12px);
  border: 1px solid var(--nms-hud-border);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.6), inset 0 0 16px rgba(0, 229, 255, 0.05);
}

.inv-slot {
  background: rgba(10, 22, 38, 0.75);
  border: 1px solid rgba(0, 229, 255, 0.25);
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  min-height: 48px;
}

.inv-slot:hover, .inv-slot:active {
  border-color: var(--nms-cyan);
  background: rgba(0, 229, 255, 0.16);
  box-shadow: 0 0 18px var(--nms-cyan-glow);
  transform: scale(1.02);
}

.inv-slot.supercharged {
  background: radial-gradient(circle, rgba(168, 85, 247, 0.35) 0%, rgba(10, 18, 32, 0.9) 100%) !important;
  border-color: #c084fc !important;
  box-shadow: 0 0 20px rgba(192, 132, 252, 0.6), inset 0 0 12px rgba(192, 132, 252, 0.35) !important;
  animation: superchargePulse 2s infinite alternate;
}

@keyframes superchargePulse {
  0% { filter: brightness(1); }
  100% { filter: brightness(1.35); box-shadow: 0 0 28px rgba(192, 132, 252, 0.85); }
}

.synergy-link-weapon { border-left: 3px solid #ef4444 !important; }
.synergy-link-shield { border-left: 3px solid #3b82f6 !important; }
.synergy-link-engine { border-left: 3px solid #facc15 !important; }
.synergy-link-scanner { border-left: 3px solid #10b981 !important; }

/* ==========================================================================
   8. SPACE FLIGHT, COCKPIT & WARP SYSTEMS
   ========================================================================== */
#cockpit-hud {
  position: fixed;
  bottom: max(16px, env(safe-area-inset-bottom));
  left: 50%;
  transform: translateX(-50%);
  width: min(680px, 94vw);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  pointer-events: none;
  z-index: 115;
}

.flight-gauge-arc {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(3, 10, 24, 0.9) 60%, transparent 62%),
              conic-gradient(var(--nms-cyan) calc(var(--gauge-val, 75) * 1%), rgba(0, 229, 255, 0.15) 0);
  border: 1px solid rgba(0, 229, 255, 0.4);
  box-shadow: 0 0 15px rgba(0, 229, 255, 0.25);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(6px);
}

#hyperspace-warp-tunnel {
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at center, #020614 0%, #000 100%);
  z-index: 280;
  display: none;
  overflow: hidden;
}

.warp-streak-line {
  position: absolute;
  width: 2px;
  background: linear-gradient(180deg, transparent 0%, var(--nms-cyan) 60%, #fff 100%);
  animation: warpStreakFall 0.4s linear infinite;
  box-shadow: 0 0 10px var(--nms-cyan-glow);
}

@keyframes warpStreakFall {
  0% { transform: translateY(-100vh) scaleY(1); opacity: 0; }
  50% { opacity: 1; }
  100% { transform: translateY(100vh) scaleY(3); opacity: 0; }
}

/* ==========================================================================
   9. MOBILE TOUCH, RADIAL WHEEL & RADAR HUD
   ========================================================================== */
#mobile-touch-controls {
  position: fixed;
  bottom: max(20px, env(safe-area-inset-bottom));
  left: 0;
  right: 0;
  padding: 0 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  pointer-events: none;
  z-index: 150;
}

.touch-btn-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba(6, 16, 32, 0.7);
  border: 1.5px solid rgba(0, 229, 255, 0.4);
  box-shadow: 0 0 15px rgba(0, 229, 255, 0.25);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  backdrop-filter: blur(8px);
  touch-action: manipulation;
  transition: all 0.15s ease;
}

.touch-btn-circle:active {
  background: rgba(0, 229, 255, 0.3);
  transform: scale(0.92);
  border-color: #fff;
  box-shadow: 0 0 25px var(--nms-cyan-glow);
}

#mobile-radial-menu {
  position: fixed;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(7, 14, 24, 0.95) 45%, rgba(0, 229, 255, 0.2) 100%);
  border: 1.5px solid var(--nms-cyan);
  box-shadow: 0 0 35px var(--nms-cyan-glow);
  z-index: 260;
  display: none;
  transform: translate(-50%, -50%) scale(0.9);
  transition: transform 0.15s cubic-bezier(0.18, 0.89, 0.32, 1.28);
  pointer-events: auto;
}

#mobile-radial-menu.active {
  display: block;
  transform: translate(-50%, -50%) scale(1);
}

#minimap-radar-container {
  position: fixed;
  bottom: max(16px, env(safe-area-inset-bottom));
  right: max(16px, env(safe-area-inset-right));
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background: rgba(3, 8, 16, 0.85);
  border: 1.5px solid var(--nms-cyan);
  box-shadow: 0 0 20px var(--nms-cyan-glow);
  z-index: 125;
  overflow: hidden;
  backdrop-filter: blur(8px);
  touch-action: none;
}

.radar-sweep-beam {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(from 0deg at 50% 50%, rgba(0, 229, 255, 0.35) 0deg, transparent 60deg, transparent 360deg);
  animation: radarRotate 3s linear infinite;
}

@keyframes radarRotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* ==========================================================================
   10. MODALS, BUILD MENU & TERMINALS
   ========================================================================== */
#build-menu-modal {
  position: fixed;
  bottom: max(24px, env(safe-area-inset-bottom));
  left: 50%;
  transform: translateX(-50%);
  width: 92%;
  max-width: 880px;
  background: var(--nms-card-bg);
  border: 1px solid var(--nms-cyan);
  border-top: 3px solid var(--nms-cyan);
  border-radius: 6px;
  padding: 16px 20px;
  z-index: 130;
  display: none;
  flex-direction: column;
  gap: 12px;
  box-shadow: 0 0 45px rgba(0, 229, 255, 0.25);
  backdrop-filter: blur(12px);
}

#refiner-modal,
#trade-terminal-modal,
#nexus-mission-modal,
#harmonic-terminal-modal {
  position: fixed;
  inset: 0;
  background: rgba(2, 6, 18, 0.9);
  backdrop-filter: blur(14px);
  z-index: 200;
  display: none;
  align-items: center;
  justify-content: center;
}

/* ==========================================================================
   11. ACCESSIBILITY, PERFORMANCE & COMFORT SAFEGUARDS
   ========================================================================== */
#performance-mini-hud {
  position: fixed;
  bottom: max(10px, env(safe-area-inset-bottom));
  left: max(12px, env(safe-area-inset-left));
  background: rgba(4, 10, 20, 0.75);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 4px;
  padding: 3px 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: 'Rajdhani', monospace;
  font-size: 11px;
  z-index: 100;
  backdrop-filter: blur(4px);
}

body.battery-saver-mode .scanlines,
body.battery-saver-mode .vignette {
  display: none !important;
}

body.battery-saver-mode * {
  backdrop-filter: none !important;
  box-shadow: none !important;
}

body.high-contrast-mode {
  --nms-cyan: #00ffff !important;
  --nms-yellow: #ffff00 !important;
  --nms-red: #ff0055 !important;
  --nms-hud-bg: rgba(0, 0, 0, 0.96) !important;
  --nms-hud-border: #ffffff !important;
}

/* 120Hz ProMotion GPU Compositing */
.nms-hud-layer,
#compass-bar,
#visor-target-card,
#cockpit-hud,
#mobile-touch-controls {
  will-change: transform, opacity;
  transform: translateZ(0);
  backface-visibility: hidden;
}

/* ==========================================================================
   12. 24TH UPDATE EXPANSIONS (UI-140 ~ UI-145)
   ========================================================================== */
/* UI-140: Jetpack Dual Thrust Flare & Ascent Arc */
.jetpack-thrust-flare {
  position: absolute;
  bottom: -15px;
  width: 14px;
  height: 28px;
  background: linear-gradient(180deg, #fff 0%, var(--nms-cyan) 50%, transparent 100%);
  filter: drop-shadow(0 0 10px var(--nms-cyan));
  animation: thrustFlicker 0.08s infinite alternate;
}

@keyframes thrustFlicker {
  0% { transform: scaleY(1); opacity: 0.8; }
  100% { transform: scaleY(1.3); opacity: 1; }
}

/* UI-141: Portal Event Horizon Chromatic Distortion */
.portal-horizon-transit {
  animation: portalDistort 0.5s ease-out;
}

@keyframes portalDistort {
  0% { filter: blur(0px) hue-rotate(0deg); transform: scale(1); }
  50% { filter: blur(8px) hue-rotate(180deg); transform: scale(1.08); }
  100% { filter: blur(0px) hue-rotate(360deg); transform: scale(1); }
}

/* UI-142: Quick Ammo Reload Arc */
.ammo-reload-arc {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-top-color: var(--nms-yellow);
  animation: reloadSpin 0.7s cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes reloadSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* UI-143: Biome Sonar Pulse Overlay */
.biome-sonar-wave {
  width: 160px;
  height: 160px;
  border-radius: 50%;
  border: 1.5px solid #a855f7;
  box-shadow: 0 0 25px rgba(168, 85, 247, 0.6);
  animation: sonarFlux 2s infinite ease-out;
}

@keyframes sonarFlux {
  0% { transform: scale(0.3); opacity: 1; }
  100% { transform: scale(2.4); opacity: 0; }
}

/* UI-144: Bulk Trade Cascade Gold Particles */
.units-cascade-banner {
  background: linear-gradient(135deg, rgba(30, 24, 4, 0.95) 0%, rgba(12, 10, 2, 0.98) 100%);
  border: 1.5px solid #facc15;
  box-shadow: 0 0 35px rgba(250, 204, 21, 0.6);
  color: #fef08a;
  animation: cascadeGlow 1s infinite alternate;
}

@keyframes cascadeGlow {
  0% { filter: brightness(1); }
  100% { filter: brightness(1.25) drop-shadow(0 0 20px #facc15); }
}

/* UI-145: Virtual Keyboard Viewport Shield */
body.virtual-keyboard-open canvas {
  height: 100dvh !important;
  max-height: 100dvh !important;
}

body.virtual-keyboard-open .modal-overlay {
  align-items: flex-start !important;
  padding-top: max(20px, env(safe-area-inset-top)) !important;
}

/* ==========================================================================
   13. 25TH UPDATE EXPANSIONS (UI-146 ~ UI-151)
   ========================================================================== */
/* UI-146: Stellar Nebula Panoramic Overlay */
#stellar-nebula-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 85;
  background: 
    radial-gradient(circle at 20% 30%, rgba(168, 85, 247, 0.25) 0%, transparent 50%),
    radial-gradient(circle at 80% 70%, rgba(0, 229, 255, 0.2) 0%, transparent 55%),
    radial-gradient(circle at 50% 50%, rgba(217, 70, 239, 0.15) 0%, transparent 60%);
  opacity: 0;
  transition: opacity 1s ease-in-out;
}

.nebula-active {
  opacity: 1 !important;
  animation: nebulaDrift 20s infinite alternate ease-in-out;
}

@keyframes nebulaDrift {
  0% { transform: scale(1) rotate(0deg); }
  100% { transform: scale(1.08) rotate(2deg); }
}

/* UI-147: Racial Heraldry 3D Rotation Badge */
.racial-heraldry-badge {
  width: 48px;
  height: 48px;
  transform-style: preserve-3d;
  animation: heraldrySpin 6s infinite linear;
}

@keyframes heraldrySpin {
  0% { transform: rotateY(0deg); }
  100% { transform: rotateY(360deg); }
}

.heraldry-gek { filter: drop-shadow(0 0 12px #facc15); color: #facc15; }
.heraldry-korvax { filter: drop-shadow(0 0 12px #60a5fa); color: #60a5fa; }
.heraldry-vykeen { filter: drop-shadow(0 0 12px #ef4444); color: #ef4444; }

/* UI-148: Starship Deflector Shield Fast Recharge */
#ship-shield-fast-recharge {
